REUSEP_CPP = r"""#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
#include <stdint.h>
#include <vector>
int64_t reusep_init();std::vector<int64_t> reusep_info(int64_t,int64_t,int64_t,int64_t);
void reusep_run(std::vector<int64_t>,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t,int64_t);
"""
_REUSEP_MODULE=[]

def reusep_module():
    if not _REUSEP_MODULE:
        target='-gencode=arch=compute_90a,code=sm_90a' if torch.cuda.get_device_capability()==(9,0) else '-gencode=arch=compute_120,code=sm_120'
        mod=load_inline(name='muse_smallm_reusep_'+hashlib.sha256(REUSEP_CUDA.encode()).hexdigest()[:12],
            cpp_sources=REUSEP_CPP,cuda_sources=REUSEP_CUDA,functions=['reusep_init','reusep_info','reusep_run'],
            no_implicit_headers=True,with_pytorch_error_handling=False,
            extra_cuda_cflags=['-O3','-std=c++20','-lineinfo',target],verbose=False)
        mod.optin=mod.reusep_init();_REUSEP_MODULE.append(mod)
    return _REUSEP_MODULE[0]

def reusep_bind(state):
    reusep_module()
    state['reusep_counters']={mode:torch.zeros(64,device=state['gs13'].device,dtype=torch.int32) for mode in (0,2)}
    return state

def reusep_geometry(state,m,mode=0,trace=False,stages=2):
    resident,regs,local,smem=reusep_module().reusep_info(mode,int(trace),stages,m)
    if not resident:raise ValueError('reuse has no resident CTA')
    return min(264,state['sms']*resident),regs,local,smem,resident

def reusep_experts(data,state,mode=0,trace=False,stamps=None):
    x=data['hidden_states'].contiguous();m=x.shape[0];dev=x.device;p=m*8
    if m>32:raise ValueError('reuse accepts at most 32 tokens')
    stages=2;grid,*_=reusep_geometry(state,m,mode,trace,stages)
    inter=torch.empty((p,4096),device=dev,dtype=torch.bfloat16);y=torch.empty((p,4096),device=dev);ss=torch.empty(p,device=dev)
    out=torch.empty_like(x);ids=data['topk_ids'].int().contiguous();tw=data['topk_weights'].float().contiguous();bank=state['banks']['lop3']
    ts=[x,ids,tw,state['pnw'],bank['w13p'],bank['w2p'],state['gs13'],state['gs2'],inter,y,ss,state['reusep_counters'][mode],out]
    if trace and (stamps is None or stamps.shape!=(grid,1040)):raise ValueError('reuse trace needs [grid,1040] int64')
    reusep_module().reusep_run([t.data_ptr() for t in ts]+[stamps.data_ptr() if trace else 0],m,data['config']['local_start'],
        stages,grid,torch.cuda.current_stream(dev).cuda_stream,mode,int(trace))
    return out
